const SLOTS=['weapon','armor','potion','charm','shield'];
const ITEMS=[{"id": "leather-armor", "quest": "0-0", "name": "Leather Armor", "slot": "armor", "rarity": "Uncommon", "guard": 1, "attack": 0, "knowledge": 0, "story": "A+ repairs and reinforces your armor. Your first piece of this equipment."}, {"id": "chainmail-armor", "quest": "0-1", "name": "Chainmail Armor", "slot": "armor", "rarity": "Uncommon", "guard": 2, "attack": 0, "knowledge": 0, "story": "A+ repairs and reinforces your armor. An upgrade earned by completing the next module."}, {"id": "plate-armor", "quest": "0-2", "name": "Plate Armor", "slot": "armor", "rarity": "Rare", "guard": 3, "attack": 0, "knowledge": 0, "story": "A+ repairs and reinforces your armor. An upgrade earned by completing the next module."}, {"id": "minor-potion", "quest": "1-0", "name": "Minor Healing Potion", "slot": "potion", "rarity": "Uncommon", "guard": 0, "attack": 0, "knowledge": 0, "story": "Network+ keeps the adventure running. Restore health once per battle; your flask refills for the next encounter.", "heal": 25}, {"id": "greater-potion", "quest": "1-1", "name": "Greater Healing Potion", "slot": "potion", "rarity": "Uncommon", "guard": 0, "attack": 0, "knowledge": 0, "story": "Network+ keeps the adventure running. Restore health once per battle; your flask refills for the next encounter.", "heal": 40}, {"id": "restoration-elixir", "quest": "1-2", "name": "Restoration Elixir", "slot": "potion", "rarity": "Rare", "guard": 0, "attack": 0, "knowledge": 0, "story": "Network+ keeps the adventure running. Restore health once per battle; your flask refills for the next encounter.", "heal": 60}, {"id": "wooden-sword", "quest": "2-0", "name": "Wooden Sword", "slot": "weapon", "rarity": "Uncommon", "guard": 0, "attack": 2, "knowledge": 0, "story": "Security+ sharpens your offensive power. Your first piece of this equipment."}, {"id": "steel-sword", "quest": "2-1", "name": "Steel Sword", "slot": "weapon", "rarity": "Uncommon", "guard": 0, "attack": 4, "knowledge": 0, "story": "Security+ sharpens your offensive power. An upgrade earned by completing the next module."}, {"id": "runic-sword", "quest": "2-2", "name": "Runic Sword", "slot": "weapon", "rarity": "Rare", "guard": 0, "attack": 6, "knowledge": 0, "story": "Security+ sharpens your offensive power. An upgrade earned by completing the next module."}];
ITEMS.push(...CLOUD_ITEMS);
for (const [core,slot,names,values] of [
 [7,'potion',['Pathfinder Tonic','Trunkkeeper Flask','Convergence Elixir'],[25,40,60]],
 [8,'shield',['Watchkeeper Buckler','Incident Ward','Recovery Aegis'],[1,2,3]]
]) names.forEach((name,tier)=>ITEMS.push({id:`study-${core}-${tier}`,studyCore:core,tier,requiredClears:(core===7?[2,4,6]:[2,3,4])[tier],name,slot,rarity:tier===2?'Rare':'Uncommon',attack:0,knowledge:0,guard:slot==='shield'?values[tier]:0,heal:slot==='potion'?values[tier]:0,story:core===7?'CCNA keeps the network and your adventure running. Your flask refills each battle.':'CySA+ turns investigation and response knowledge into protection.'}));
// Stable one/two/three-branch milestones do not move when a course grows.
for(const [core,slot,names] of [
 [9,'shield',['Cloudwatch Buckler','Governance Ward','Azure Bastion']],
 [10,'charm',['Architect Spark','Resilience Sigil','Cloud Citadel Charm']],
 [11,'shield',['Identity Buckler','Trust Ward','Compliance Aegis']],
 [12,'charm',['Discovery Spark','Insight Sigil','Digital Horizon Charm']],
 [13,'charm',['Plan Rune','Statekeeper Sigil','Runesmith Charm']],
 [14,'armor',['Apprentice Tunic','Servicekeeper Mail','Linux Warden Armor']]
])names.forEach((name,tier)=>ITEMS.push({id:`study-${core}-${tier}`,studyCore:core,tier,requiredClears:tier+1,name,slot,rarity:tier===2?'Rare':'Uncommon',attack:0,knowledge:slot==='charm'?[2,4,6][tier]:0,guard:['armor','shield'].includes(slot)?tier+1:0,heal:0,story:'A keepsake earned by mastering a specialist study branch. Its bonus travels with your hero through every realm.'}));
function advancedItemEarned(item,s) {
 const topics=STUDY_TOPICS.filter(t=>t.core===item.studyCore);
 return topics.length>0 && topics.filter(t=>s.academy?.done?.includes(t.id)).length>=item.requiredClears;
}
function grantAdvancedLoot() {
 for(const item of ITEMS.filter(i=>i.studyCore)) {
  if(!advancedItemEarned(item,state)||state.inventory.includes(item.id))continue;
  state.inventory.push(item.id);
  const old=itemById(state.equipment[item.slot]);
  if(!old||itemPower(item)>itemPower(old))state.equipment[item.slot]=item.id;
 }
}
function itemOrigin(item) {
 if(item.studyCore)return certificationName(item.studyCore)+' · '+['First','Second','Final'][item.tier]+' expedition milestone · Clear '+item.requiredClears+' branches';
 const [realm,chapter]=item.quest.split('-').map(Number);
 return realms[realm].cert+' · '+realms[realm].chapters[chapter][0];
}
function itemById(id){return ITEMS.find(i=>i.id===id);}
function itemPower(item){return item.attack+item.knowledge+item.guard+(item.heal||0);}
function itemBonus(item){return [item.heal?`Restore ${item.heal} HP · once per battle · no enemy counterattack`:'',item.attack?`+${item.attack} attack damage`:'',item.knowledge?`+${item.knowledge} knowledge damage`:'',item.guard?`−${item.guard} damage taken per hit`:''].filter(Boolean).join(' · ');}
function itemIcon(item){const slot=item?.slot||'potion';const shapes={charm:'<path d="M8 3h8l4 7-8 11L4 10zM4 10h16M8 3l4 18 4-18"/>',shield:'<path d="M12 3l8 4v6c0 4-8 8-8 8s-8-4-8-8V7zM12 7v10M8 11h8"/>',weapon:'<path d="M12 4l4 4-8 8-4-4zM7 15l-3 5m-1-5l6 6M12 4l6-1-2 5"/>',potion:'<path d="M9 3h6v6l4 5v5l-2 2H7l-2-2v-5l4-5zM8 3h8M6 15h12M12 12v6M9 15h6"/>',armor:'<path d="M8 3h8l5 4-3 5-2-1v10H8V11l-2 1-3-5z"/>'};return `<span class="item-icon ${item?.rarity==='Rare'?'rare':''}" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${shapes[slot]}</svg></span>`;}
function migrateGear(s){
 s.inventory=ITEMS.filter(i=>i.studyCore?advancedItemEarned(i,s):s.done.includes(i.quest)||studyRewardTiers(s,Number(i.quest.split('-')[0]))[Number(i.quest.split('-')[1])]).map(i=>i.id);
 if(s.gearRevision!==3||!s.equipment){
   s.equipment={weapon:null,armor:null,potion:null,charm:null,shield:null};
   for(const key of s.inventory){const item=itemById(key),old=itemById(s.equipment[item.slot]);if(!old||itemPower(item)>itemPower(old))s.equipment[item.slot]=key;}
   s.gearRevision=3;
 }
 if(typeof s.equipment!=='object'||Array.isArray(s.equipment))throw Error('Invalid equipment');
 for(const slot of SLOTS){if((slot==='charm'||slot==='shield')&&s.equipment[slot]===undefined){s.equipment[slot]=null;for(const item of ITEMS.filter(i=>i.slot===slot&&s.inventory.includes(i.id)))s.equipment[slot]=item.id;}const key=s.equipment[slot];if(key!==null&&(!s.inventory.includes(key)||itemById(key)?.slot!==slot))throw Error('Invalid equipment');}
 return s;
}
function gearStats(s=state){const stats={attack:10,knowledge:20+Math.min(Math.floor(s.xp/100),8),guard:0,heal:0};for(const slot of SLOTS){const item=itemById(s.equipment[slot]);if(item){stats.attack+=item.attack;stats.knowledge+=item.knowledge;stats.guard+=item.guard;stats.heal+=item.heal||0;}}return stats;}
function combatStats(){return state.battle?.loadout||gearStats();}
function grantLoot(r,c){const item=ITEMS.find(i=>i.quest===`${r}-${c}`);if(!item||state.inventory.includes(item.id))return {item,autoEquipped:false};state.inventory.push(item.id);const old=itemById(state.equipment[item.slot]);const autoEquipped=!old||itemPower(item)>itemPower(old);if(autoEquipped)state.equipment[item.slot]=item.id;return {item,autoEquipped};}
function equipmentBadges(){return `<div class="equipment-badges">${SLOTS.map(slot=>{const item=itemById(state.equipment[slot]);return `<span title="${item?item.name+': '+itemBonus(item):'No '+slot+' equipped'}">${itemIcon(item||{slot})}<small>${item?item.name:'Empty '+slot}</small></span>`;}).join('')}</div>`;}
function openHero(){document.querySelector('#journal').close();go('hero');}
function equipItem(key){const item=itemById(key);if(!item||!state.inventory.includes(key))return;if(state.battle){toast('Finish or flee your battle before changing equipment.');return;}state.equipment[item.slot]=key;save();heroSheet();toast(item.name+' equipped.');}
function unequipItem(slot){if(!SLOTS.includes(slot))return;if(state.battle){toast('Finish or flee your battle before changing equipment.');return;}state.equipment[slot]=null;save();heroSheet();}
function heroSheet(){const h=HEROES[state.hero],stats=combatStats();app.innerHTML=`<button class="back" onclick="go('home')">← Return to camp</button><div class="eyebrow">One hero. An unfolding story.</div><h1>Your adventurer</h1><p class="muted">The same hero travels through all realms. Every first quest clear adds a keepsake to your adventure.</p><div class="hero-sheet-layout"><aside class="hero-sheet-profile"><img class="sheet-portrait" src="assets/${h.id}.png?v=simple2" alt="${h.name}" width="400" height="500"><div class="sheet-profile-copy"><span class="tag">${h.role} · Level ${level()}</span><h2>${h.name}</h2><p>${state.xp} XP · ${state.done.length}/${questCount()} quests · ${state.inventory.length}/${ITEMS.length} items</p><div class="bar"><span style="width:${state.xp%100}%"></span></div><small class="muted">${100-state.xp%100} XP to the next level</small><button onclick="openCharacters()">Change appearance</button></div></aside><div class="hero-sheet-content"><div class="hero-stats"><div><strong>${stats.attack}</strong><span>Attack damage</span></div><div><strong>${stats.knowledge}</strong><span>Knowledge damage</span></div><div><strong>${stats.guard}</strong><span>Damage blocked / hit</span></div></div><p class="health">Base health: ${learningBonuses().maxHp} · Training applies in every realm.</p><p>${Object.entries(learningBonuses().resistance).map(([type,n])=>type+": −"+n).join(" · ")}</p><h2>Your classifications</h2><p>${Object.values(CERTIFICATIONS).filter(c=>c.realm!==undefined&&c.code!=="Support basics").map(c=>c.name+": "+c.role+" · "+c.reward).join("<br>")}</p><h2>Equipped gear</h2><p class="muted small-copy">Security+ upgrades your sword. A+ upgrades your armor. Network+ upgrades your healing potion. AWS upgrades your spell charm. Azure upgrades your shield. Potions refill between battles. Gear bonuses apply in every realm.</p>${state.battle?'<p class="gear-notice">Your battle is saved. Finish it or flee to change equipment; these are your battle stats.</p>':''}<div class="equipped-slots">${SLOTS.map(slot=>{const item=itemById(state.equipment[slot]);return `<article class="equipped-slot">${itemIcon(item||{slot})}<div><span class="tag">${slot}</span><h3>${item?item.name:'Nothing equipped'}</h3><p>${item?itemBonus(item):'Earn gear by completing a quest.'}</p></div>${item?`<button ${state.battle?'disabled':''} onclick="unequipItem('${slot}')">Remove</button>`:''}</article>`;}).join('')}</div><div class="section-head"><h2>Your inventory</h2><span class="muted">${state.inventory.length} collected</span></div>${state.inventory.length?'':'<div class="empty-inventory"><h3>Your story starts here.</h3><p>Complete your first quest to earn a piece of gear. Stronger new gear is equipped automatically.</p><button class="primary" onclick="continueQuest()">Begin a quest →</button></div>'}<div class="inventory-grid">${ITEMS.filter(i=>state.inventory.includes(i.id)).map(item=>itemCard(item)).join('')}</div><details class="loot-guide"><summary>See the rewards ahead · ${ITEMS.length-state.inventory.length} undiscovered</summary><div class="upcoming-loot">${ITEMS.filter(i=>!state.inventory.includes(i.id)).map(item=>`<div>${itemIcon(item)}<span><strong>${item.name}</strong><small>${itemOrigin(item)}<br>${itemBonus(item)}</small></span></div>`).join('')||'<p>All treasures discovered!</p>'}</div></details></div></div>`;}
function itemCard(item){const equipped=state.equipment[item.slot]===item.id;return `<article class="inventory-item ${item.rarity==='Rare'?'rare-item':''}"><div class="item-card-heading">${itemIcon(item)}<span><small class="tag">${item.rarity} · ${item.slot}</small><h3>${item.name}</h3></span></div><strong class="item-bonus">${itemBonus(item)}</strong><p>${item.story}</p><small class="muted">Earned: ${itemOrigin(item)}</small><button ${equipped||state.battle?'disabled':''} onclick="equipItem('${item.id}')">${equipped?'✓ Equipped':state.battle?'Available after battle':'Equip '+item.slot}</button></article>`;}
function lootReward(r,c){const item=ITEMS.find(i=>i.quest===`${r}-${c}`);const freshLoot=lastReward?.first;return `<section class="quest-loot"><div class="eyebrow">${freshLoot?'Quest treasure':'Already in your collection'}</div><div class="loot-reveal">${itemIcon(item)}<div><span class="tag">${item.rarity} · ${item.slot}</span><h2>${item.name}</h2><strong>${itemBonus(item)}</strong></div></div><p>${item.story}</p><p class="loot-state">${freshLoot?(lastReward.autoEquipped?'✓ Equipped automatically · ready for your next quest':'✓ Added to your inventory · your current gear stays equipped'):'Practice clear · no duplicate item or rewards'}</p><button onclick="openHero()">View your hero & inventory →</button></section>`;}
